// Package database builds validated MariaDB provisioning statements.
// Identifiers are whitelisted by security.ValidateSQLIdentifier before any
// interpolation; passwords are passed as escaped literals generated by the
// panel (never user-typed SQL). No user input is ever executed as raw SQL.
package database

import (
	"fmt"
	"strings"

	"github.com/Udhayaboopathi/hPanel-wp/internal/security"
)

// EscapeLiteral escapes a generated password for a single-quoted MySQL literal.
func EscapeLiteral(s string) string {
	r := strings.NewReplacer("\\", "\\\\", "'", "\\'", "\x00", "")
	return r.Replace(s)
}

func CreateDatabaseSQL(dbName string) (string, error) {
	if err := security.ValidateSQLIdentifier(dbName); err != nil {
		return "", err
	}
	return fmt.Sprintf("CREATE DATABASE IF NOT EXISTS `%s` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;", dbName), nil
}

func CreateUserSQL(dbName, dbUser, password string) ([]string, error) {
	if err := security.ValidateSQLIdentifier(dbName); err != nil {
		return nil, err
	}
	if err := security.ValidateDBUser(dbUser); err != nil {
		return nil, err
	}
	pw := EscapeLiteral(password)
	return []string{
		fmt.Sprintf("CREATE USER IF NOT EXISTS '%s'@'%%' IDENTIFIED BY '%s';", dbUser, pw),
		fmt.Sprintf("ALTER USER '%s'@'%%' IDENTIFIED BY '%s';", dbUser, pw),
		// Least privilege: only this site's database, only DML/DDL WordPress needs.
		fmt.Sprintf("GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, INDEX, DROP, CREATE TEMPORARY TABLES, LOCK TABLES ON `%s`.* TO '%s'@'%%';", dbName, dbUser),
		"FLUSH PRIVILEGES;",
	}, nil
}

func DropDatabaseSQL(dbName, dbUser string) ([]string, error) {
	if err := security.ValidateSQLIdentifier(dbName); err != nil {
		return nil, err
	}
	if err := security.ValidateDBUser(dbUser); err != nil {
		return nil, err
	}
	return []string{
		fmt.Sprintf("DROP DATABASE IF EXISTS `%s`;", dbName),
		fmt.Sprintf("DROP USER IF EXISTS '%s'@'%%';", dbUser),
		"FLUSH PRIVILEGES;",
	}, nil
}

// DropDatabaseOnlySQL drops only the site's database. It is used when the
// site was provisioned on the shared common DB user (privilege fallback):
// that user must NEVER be dropped because every other site and the panel's
// provisioning path depend on it.
func DropDatabaseOnlySQL(dbName string) ([]string, error) {
	if err := security.ValidateSQLIdentifier(dbName); err != nil {
		return nil, err
	}
	return []string{
		fmt.Sprintf("DROP DATABASE IF EXISTS `%s`;", dbName),
	}, nil
}

func RotatePasswordSQL(dbUser, newPassword string) ([]string, error) {
	if err := security.ValidateDBUser(dbUser); err != nil {
		return nil, err
	}
	return []string{
		fmt.Sprintf("ALTER USER '%s'@'%%' IDENTIFIED BY '%s';", dbUser, EscapeLiteral(newPassword)),
		"FLUSH PRIVILEGES;",
	}, nil
}

func ProvisionSQL(dbName, dbUser, password string) ([]string, error) {
	db, err := CreateDatabaseSQL(dbName)
	if err != nil {
		return nil, err
	}
	rest, err := CreateUserSQL(dbName, dbUser, password)
	if err != nil {
		return nil, err
	}
	return append([]string{db}, rest...), nil
}

// SizeQuery returns total bytes for one schema (run as root inside MariaDB).
func SizeQuery(dbName string) (string, error) {
	if err := security.ValidateSQLIdentifier(dbName); err != nil {
		return "", err
	}
	return fmt.Sprintf("SELECT COALESCE(SUM(data_length+index_length),0) FROM information_schema.tables WHERE table_schema='%s';", dbName), nil
}
